package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.json.*;import org.junit.*;
/** Explicit query masks reduce the original source read set, never its permission or traversal budget. */
public final class ProjectSearchExcludeTest {
 private Path root;private static final String CHECKOUT="11111111-1111-1111-1111-111111111111";
 @Before public void create()throws Exception{root=Files.createTempDirectory("pw-source-exclude-");}
 @After public void close()throws Exception{try(var files=Files.walk(root)){for(Path p:files.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.deleteIfExists(p);}}
 private void file(String path,String text)throws Exception{Path target=root.resolve(path);Files.createDirectories(target.getParent());Files.write(target,text.getBytes(StandardCharsets.UTF_8));}
 private JSONObject input()throws Exception{return new JSONObject().put("mode","text").put("query","needle");}
 private JSONObject search(JSONObject input)throws Exception{return ProjectFileQueries.search(root.toFile(),CHECKOUT,input,()->{});}
 @Test public void excludedFilesAreNotHashedOrDecodedAndDoNotSpendTheContentByteBudget()throws Exception{file("keep.txt","needle\n");file("ignore/huge.txt","x".repeat(1024*1024));AtomicInteger checks=new AtomicInteger();JSONObject result=ProjectFileQueries.search(root.toFile(),CHECKOUT,input().put("exclude","ignore/**"),checks::incrementAndGet);assertEquals(1,result.getJSONArray("matches").length());assertEquals("keep.txt",result.getJSONArray("matches").getJSONObject(0).getString("path"));assertEquals(1,result.getInt("excludedByQuery"));assertEquals(1,result.getInt("scannedFiles"));assertEquals(7,result.getLong("scannedBytes"));assertTrue("excluded content unexpectedly scanned, checks="+checks.get(),checks.get()<64);assertTrue(result.getBoolean("coverageComplete"));assertTrue(result.getBoolean("queryExclusionsUseOriginalEnumerationBudget"));}
 @Test public void omissionAndEmptyMaskRetainTheOriginalExactLiteralIdentityAndResponse()throws Exception{file("a.txt","needle\n");JSONObject a=search(input()),b=search(input().put("exclude",""));assertEquals(a.toString(),b.toString());assertFalse(a.has("exclude"));assertFalse(a.has("excludedByQuery"));JSONObject oldIdentity=new JSONObject().put("checkoutId",CHECKOUT).put("manifestHash",a.getString("manifestHash")).put("mode","text").put("query","needle").put("syntax","literal").put("path","").put("include","**").put("hidden",false).put("caseSensitive",true).put("contextBefore",0).put("contextAfter",0);assertEquals(ProjectSources.digest(oldIdentity),a.getString("queryHash"));}
 @Test public void cursorBindsTheMaskEvenWhenBothMasksCurrentlyExcludeNoFiles()throws Exception{file("a.txt","needle\n");file("z.txt","needle\n");JSONObject query=input().put("limit",1).put("exclude","skip/**"),first=search(query);assertTrue(first.getBoolean("hasMore"));JSONObject cursor=first.getJSONObject("nextCursor");assertThrows(SecurityException.class,()->search(new JSONObject(query.toString()).put("exclude","none/**").put("cursor",cursor)));JSONObject absent=new JSONObject(query.toString());absent.remove("exclude");assertThrows(SecurityException.class,()->search(absent.put("cursor",cursor)));JSONObject last=search(new JSONObject(query.toString()).put("cursor",cursor));assertEquals("z.txt",last.getJSONArray("matches").getJSONObject(0).getString("path"));assertFalse(last.getBoolean("hasMore"));}
 @Test public void excludedContentChangesDoNotInvalidateItsUnchangedParticipatingSourceButIncludedChangesDo()throws Exception{file("a.txt","needle\n");file("z.txt","needle\n");file("ignore/private.txt","old");JSONObject query=input().put("limit",1).put("exclude","ignore/**"),first=search(query);file("ignore/private.txt","different private bytes");JSONObject last=search(new JSONObject(query.toString()).put("cursor",first.getJSONObject("nextCursor")));assertEquals("z.txt",last.getJSONArray("matches").getJSONObject(0).getString("path"));assertEquals(first.getString("manifestHash"),last.getString("manifestHash"));file("z.txt","needle changed\n");assertThrows(SecurityException.class,()->search(new JSONObject(query.toString()).put("cursor",first.getJSONObject("nextCursor"))));}
 @Test public void pathAndRegexFiltersUseTheSameMaskWithoutReopeningHiddenOrDependencyRoots()throws Exception{file("src/Keep.java","needle 12\n");file("src/KeepTest.java","needle 13\n");file("node_modules/Hack.java","needle 14\n");file(".hidden.java","needle 15\n");JSONObject paths=search(new JSONObject().put("mode","path").put("query","**/*.java").put("exclude","**/*Test.java"));assertEquals(1,paths.getJSONArray("matches").length());assertEquals("src/Keep.java",paths.getJSONArray("matches").getJSONObject(0).getString("path"));JSONObject regex=search(input().put("query","needle [0-9]+").put("syntax","regex").put("exclude","**/*Test.java"));assertEquals(1,regex.getJSONArray("matches").length());assertEquals("regex_re2j_line",regex.getString("searchSyntax"));assertEquals(2,search(new JSONObject().put("mode","path").put("query","**/*.java").put("hidden",true).put("exclude","**/*Test.java")).getJSONArray("matches").length());}
 @Test public void queryExclusionsCannotTurnTheOriginalEnumerationLimitIntoAnUnboundedEmptySuccess()throws Exception{for(int i=0;i<2001;i++)file(String.format(java.util.Locale.ROOT,"file-%04d.txt",i),"x");JSONObject result=search(input().put("exclude","**"));assertEquals(0,result.getJSONArray("matches").length());assertEquals(2000,result.getInt("excludedByQuery"));assertEquals(0,result.getInt("scannedFiles"));assertFalse(result.getBoolean("enumerationComplete"));assertFalse(result.getBoolean("coverageComplete"));assertFalse(result.getBoolean("hasMore"));assertTrue(result.isNull("nextCursor"));}
 @Test public void invalidMasksAndMixedHexOptionsFailAndCancellationNeverReturnsAFalseEmptySuccess()throws Exception{file("keep.txt","needle");for(Object value:new Object[]{1,true,new JSONObject(),JSONObject.NULL,"/absolute","back\\slash","bad\0path","a".repeat(241)})assertThrows(Exception.class,()->search(input().put("exclude",value)));assertThrows(IllegalArgumentException.class,()->search(new JSONObject().put("mode","hex").put("path","keep.txt").put("query","6e").put("exclude","")));for(int i=0;i<20;i++)file("ignore/"+i+".txt","needle");AtomicInteger checks=new AtomicInteger();assertThrows(Exception.class,()->ProjectFileQueries.search(root.toFile(),CHECKOUT,input().put("exclude","ignore/**"),()->{if(checks.incrementAndGet()>12)throw new InterruptedException("original cancelled");}));}
}
